/** Save generated bytes locally. Native paths come only from the OS dialog. */
export function saveFile(blob: Blob, filename: string, doc: Document = document): Promise<boolean> {
  const native = (
    globalThis as typeof globalThis & {
      __TAURI__?: { core?: { invoke<T>(command: string, args: object): Promise<T> } };
    }
  ).__TAURI__;
  if (native) {
    if (blob.size > 32 * 1024 * 1024) return Promise.reject(new Error('Export exceeds 32 MiB.'));
    if (!native.core) return Promise.reject(new Error('Native save dialog is unavailable.'));
    return blob.arrayBuffer().then((buffer) =>
      native.core!.invoke<boolean>('save_export', {
        fileName: filename,
        bytes: Array.from(new Uint8Array(buffer)),
      }),
    );
  }
  const url = URL.createObjectURL(blob);
  const anchor = doc.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
  return Promise.resolve(true);
}

/** Existing fire-and-forget export buttons still report Native failures. */
export function saveBlob(blob: Blob, filename: string, doc: Document = document): void {
  void saveFile(blob, filename, doc).catch((error: unknown) => {
    const message =
      error instanceof Error
        ? error.message
        : ((error as { message?: string } | null)?.message ?? 'Could not save the export.');
    globalThis.alert(message);
  });
}
